CREATE or ALTER procedure [dbo].[DeleteAssetDataProfileRecords] @dataProfileLifespan int = 365 as begin BEGIN TRANSACTION; SAVE TRANSACTION DeleteDataProfilingSavePoint;
BEGIN TRY -- delete records from child tables DELETE FROM AssetDataProfile where DATEDIFF(day, updatedon, getutcdate()) > @dataProfileLifespan
COMMIT TRANSACTION END TRY BEGIN CATCH IF @@TRANCOUNT > 0 BEGIN ROLLBACK TRANSACTION DeleteDataProfilingSavePoint; -- rollback to SavePoint END END CATCH end
